    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    // Calculate which batch/feature element this thread is processing
    int64_t batch_idx = idx / normalized_elements;
    int64_t feature_idx = idx % normalized_elements;

    // Get precomputed mean and reciprocal standard deviation for this batch
    float batch_mean = mean[batch_idx];
    float batch_rstd = rstd[batch_idx];

    // Get weight and bias for this feature
    half w = weight[feature_idx];
    half b = bias[feature_idx];

    // Normalize and scale
    float val = __half2float(input[idx]);
    float normalized = (val - batch_mean) * batch_rstd;
    float result = normalized * __half2float(w) + __half2float(b);

    output[idx] = __float2half(result);
}

// Helper kernel to compute mean and variance
__global__ void mean_var_kernel(
    const half* __restrict__ input,
    float* __restrict__ mean,
    float* __restrict__ var,
    int64_t total_elements,
    int64_t normalized_elements
) {
    extern __shared__ float shared_mem[];

    int64_t batch_idx = blockIdx.x;
    int64_t tid = threadIdx.x;

    if (batch_idx >= total_elements / normalized_elements) return;

    float sum = 0.0f;
    float sum_sq = 0.0f;

    // Process all elements in this batch
    for (int64_t i = tid; i < normalized_elements; i += blockDim.x) {
        int64_t idx = batch_idx * normalized_elements + i;
        float val = __half2float(input[idx]);
        sum += val;
        sum_sq += val * val;
    }

    shared_mem[tid] = sum;
    __syncthreads();

    // Reduce within block
    for (int64_t stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shared_mem[tid] += shared_mem[tid + stride];
        }
        __syncthreads();
    }

    // Write results
    if (tid == 0) {
        mean[batch_idx] = shared_mem[0] / normalized_elements;
    }

    __syncthreads();

    // Compute variance
    shared_mem[tid] = sum_sq;
    __syncthreads();

    for (int64_t stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shared_mem[tid] += shared_mem[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float batch_mean = mean[batch_idx];
        var[batch_idx] = shared_mem[0] / normalized_elements - batch_mean * batch_mean;
    }
